#!/usr/bin/env bash
# Run all three Perl distribution suites with ASan or ASan plus leak checks.
set -euo pipefail

if [[ $# != 2 || ${2:-} != asan && ${2:-} != lsan ]]; then
    echo 'Usage: test.sh sanitizer-work-directory asan|lsan' >&2
    exit 1
fi
work=$(cd -- "$1" && pwd)
mode=$2
[[ -f $work/build-complete ]] || { echo 'Build is incomplete' >&2; exit 1; }
# Generated by build.sh in this private workspace.
source "$work/config.sh"

# ASan enlarges C stack frames. Preserve the 9999-level regression coverage
# with a finite stack large enough for the instrumented build.
stack_kb=${SEREAL_SANITIZER_STACK_KB:-65536}
[[ $stack_kb =~ ^[1-9][0-9]*$ ]] || { echo 'Invalid stack size' >&2; exit 1; }
ulimit -S -s "$stack_kb"

unset PERL5OPT
export PATH="$(dirname -- "$perl_bin"):$PATH"
export PERL5LIB="$work/source/Perl/Decoder/blib/lib:$work/source/Perl/Decoder/blib/arch:$work/source/Perl/Encoder/blib/lib:$work/source/Perl/Encoder/blib/arch"
export PERL_DESTRUCT_LEVEL=2 LD_PRELOAD="$runtime" PERL_DL_NONLAZY=1
leaks=0
[[ $mode == lsan ]] && leaks=1
export ASAN_OPTIONS="${ASAN_OPTIONS:+$ASAN_OPTIONS:}detect_leaks=$leaks:halt_on_error=1:allocator_may_return_null=1"
export LSAN_OPTIONS="${LSAN_OPTIONS:+$LSAN_OPTIONS:}exitcode=23"
rm -f "$work/$mode-passed"
printf 'PERL_DESTRUCT_LEVEL=2\nstack_kb=%s\nASAN_OPTIONS=%s\nLSAN_OPTIONS=%s\n' \
    "$stack_kb" "$ASAN_OPTIONS" "$LSAN_OPTIONS" > "$work/logs/$mode-environment.txt"

# Distinguish runtime/sandbox failures from Sereal failures. In particular,
# LSan needs to inspect other threads and cannot run under every sandbox.
if ! "$perl_bin" -e 'print "Perl $] runtime preflight; PERL_DESTRUCT_LEVEL=$ENV{PERL_DESTRUCT_LEVEL}\n"' \
    > "$work/logs/$mode-preflight.log" 2>&1; then
    cat "$work/logs/$mode-preflight.log"
    echo "$mode runtime preflight failed; Sereal tests were not run" >&2
    exit 1
fi
"$perl_bin" -MSereal::Decoder -MSereal::Encoder -e '
    print "Decoder: $INC{q(Sereal/Decoder.pm)}\n";
    print "Encoder: $INC{q(Sereal/Encoder.pm)}\n";
' > "$work/logs/$mode-modules.log" 2>&1
cat "$work/logs/$mode-modules.log"

status=0
for dist in Decoder Encoder Sereal; do
    echo "Testing $dist ($mode; PERL_DESTRUCT_LEVEL=2)"
    if ! (
        cd "$work/source/Perl/$dist"
        # Use the same harness and file patterns as make test, without
        # preloading libasan into make itself (LSan reports make's own
        # exit-time allocations, which are unrelated to Sereal).
        shopt -s nullglob
        tests=( t/*.t t/*/*/*.t )
        [[ ${#tests[@]} != 0 ]] || { echo 'No test files found' >&2; exit 1; }
        "$perl_bin" -MExtUtils::Command::MM -MTest::Harness -e \
            'undef *Test::Harness::Switches; test_harness(0, "blib/lib", "blib/arch")' \
            "${tests[@]}"
    ) > "$work/logs/$mode-$dist.log" 2>&1; then
        status=1
        echo "FAIL: $dist; see $work/logs/$mode-$dist.log"
        tail -n 40 "$work/logs/$mode-$dist.log"
    else
        echo "PASS: $dist; see $work/logs/$mode-$dist.log"
        tail -n 4 "$work/logs/$mode-$dist.log"
    fi
done
if [[ $status == 0 ]]; then
    touch "$work/$mode-passed"
fi
exit "$status"
